window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-128c9f9600d839f4"]={"versions": [{"id": "FIG-128c9f9600d839f4", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt die Bitbelegung des Control Bit Vector (CBV) innerhalb einer UDP-Network-Management-PDU dar (Byte 1). Im Architekturkontext des AUTOSAR Classic Platform UDP Network Management (UdpNm) definiert diese Struktur die Protokoll-Steuerbits zur Koordination des Netzwerkstatus und des Buszustands zwischen Steuergeräten über IP-basierte Netzwerke.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist ein 8-Bit-Feld (Byte 1) mit Einzelfeldern von Bit 7 bis Bit 0:</p>\n<ul class=\"fig-list\"><li>Bit 7: Reserviert (<code>Res</code>)\n</li><li>Bit 6: Reserviert (<code>Res</code>)\n</li><li>Bit 5: Reserviert (<code>Res</code>)\n</li><li>Bit 4: Reserviert (<code>Res</code>)\n</li><li>Bit 3: <code>NM Coordinator Sleep Ready</code> (Signalisiert Einschlafbereitschaft des NM-Koordinators)\n</li><li>Bit 2: Reserviert (<code>Res</code>), im Diagramm mit grauem Vermerk <code>R3.2 NM Coordinator ID (High Bit)</code> annotiert\n</li><li>Bit 1: Reserviert (<code>Res</code>), im Diagramm mit grauem Vermerk <code>R3.2 NM Coordinator ID (Low Bit)</code> annotiert\n</li><li>Bit 0: <code>RptMsgRequest</code> (Repeat Message Request Bit)\n</li></ul>\n<p class=\"fig-p\">Schnittstellenseitig ist das Byte Teil der übertragenen UdpNm-Botschaften und bildet Steuerflags auf Protokollebene ab.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Byte wird bei der Protokollverarbeitung ausgewertet und gesetzt:</p>\n<ul class=\"fig-list\"><li>Das Setzen von Bit 0 (<code>RptMsgRequest</code>) steuert den Eintritt bzw. Verbleib im Repeat Message State des Network-Management-Zustandsautomaten.\n</li><li>Bit 3 (<code>NM Coordinator Sleep Ready</code>) koordiniert synchronisierte Übergänge in den Schlafzustand über koordinierende Knoten hinweg.\n</li><li>Die reservierten Bits 7–4 sowie 2–1 werden standardmäßig nicht dynamisch geschaltet bzw. für abwärtskompatible Altstrukturen reserviert gehalten.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend ist das Bit-Mapping für Byte 1 der NM-PDU:</p>\n<ul class=\"fig-list\"><li>Bit 0 (<code>RptMsgRequest</code>) und Bit 3 (<code>NM Coordinator Sleep Ready</code>) besitzen spezifische Protokollfunktionen im UdpNm-Zustandsnetz.\n</li><li>Bits 7–4 sowie Bits 2–1 sind reserviert und senderseitig auf 0 zu initialisieren sowie empfängerseitig zu ignorieren, sofern keine spezifischen Protokollerweiterungen vorliegen.\n</li></ul>"}, {"id": "FIG-b413aad2fd9901b5", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt die Bitbelegung des Control Bit Vector (CBV) innerhalb der UdpNm-PDU dar. Im AUTOSAR-UdpNm-Architekturkontext definiert diese tabellarische Bitfeld-Spezifikation die Kontrollflags zur Netzwerkzustandssteuerung und Partial-Networking-Unterstützung über Ethernet/UDP.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist das Byte <code>CBV</code> mit den Bitpositionen Bit 7 bis Bit 0:</p>\n<ul class=\"fig-list\"><li>Bit 7: Reserviert (<code>Res</code>)\n</li><li>Bit 6: <code>PNI Bit</code> (Partial Network Information Bit)\n</li><li>Bit 5: Reserviert (<code>Res</code>)\n</li><li>Bit 4: <code>Active Wakeup Bit</code>\n</li><li>Bit 3: <code>NM Coordinator Sleep Ready</code>\n</li><li>Bit 2: Reserviert (<code>Res</code>), mit Hinweistext <code>R3.2 NM Coordinator ID (High Bit)</code>\n</li><li>Bit 1: Reserviert (<code>Res</code>), mit Hinweistext <code>R3.2 NM Coordinator ID (Low Bit)</code>\n</li><li>Bit 0: <code>Repeat Message Request</code>\n</li></ul>\n<p class=\"fig-p\">Das CBV-Feld fungiert als standardisierter Kommunikationsheader innerhalb des User-Data- bzw. Steuerdatenbereichs der NM-Nachricht.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Signalbits beeinflussen das Zustandsverhalten des NM-Stacks:</p>\n<ul class=\"fig-list\"><li>Bit 0 (<code>Repeat Message Request</code>) fordert den Repeat Message State an.\n</li><li>Bit 3 (<code>NM Coordinator Sleep Ready</code>) übermittelt die Schlafbereitschaft eines Koordinators.\n</li><li>Bit 4 (<code>Active Wakeup Bit</code>) signalisiert, dass der Knoten das Netzwerk aktiv aufgeweckt hat (Diagnose- und Tracking-Zwecke).\n</li><li>Bit 6 (<code>PNI Bit</code>) indiziert, ob im Datenteil der NM-Nachricht Partial-Network-Filtervektoren enthalten sind und ausgewertet werden müssen.\n</li><li>Bits 7, 5 sowie 2–1 verbleiben reserviert.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwicklungs- und Integrationshinweise:</p>\n<ul class=\"fig-list\"><li>Die Bitpositionen sind bei der Serialisierung und Deserialisierung des CBV strikt nach der Spezifikation zu decodieren.\n</li><li>Bit 6 (<code>PNI Bit</code>) bestimmt die Interpretation nachfolgender Bytes bezüglich Partial-Network-Clusteranforderungen.\n</li><li>Bit 4 (<code>Active Wakeup Bit</code>) muss bei aktiver Weckursache gesetzt und bei passivem Wecken gelöscht übertragen werden.\n</li><li>Reservierte Bits (Bits 7, 5, 2, 1) sind konform zu den Initialisierungsregeln zu handhaben.\n</li></ul>"}, {"id": "FIG-225da6df9d79a652", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt die Bitbelegung des Control Bit Vector (CBV) innerhalb der UdpNm-PDU dar. Im AUTOSAR-UdpNm-Architekturkontext definiert diese tabellarische Bitfeld-Spezifikation die Kontrollflags zur Netzwerkzustandssteuerung und Partial-Networking-Unterstützung über Ethernet/UDP.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist das Byte <code>CBV</code> mit den Bitpositionen Bit 7 bis Bit 0:</p>\n<ul class=\"fig-list\"><li>Bit 7: Reserviert (<code>Res</code>)\n</li><li>Bit 6: <code>PNI Bit</code> (Partial Network Information Bit)\n</li><li>Bit 5: Reserviert (<code>Res</code>)\n</li><li>Bit 4: <code>Active Wakeup Bit</code>\n</li><li>Bit 3: <code>NM Coordinator Sleep Ready</code>\n</li><li>Bit 2: Reserviert (<code>Res</code>), mit Hinweistext <code>R3.2 NM Coordinator ID (High Bit)</code>\n</li><li>Bit 1: Reserviert (<code>Res</code>), mit Hinweistext <code>R3.2 NM Coordinator ID (Low Bit)</code>\n</li><li>Bit 0: <code>Repeat Message Request</code>\n</li></ul>\n<p class=\"fig-p\">Das CBV-Feld fungiert als standardisierter Kommunikationsheader innerhalb des User-Data- bzw. Steuerdatenbereichs der NM-Nachricht.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Signalbits beeinflussen das Zustandsverhalten des NM-Stacks:</p>\n<ul class=\"fig-list\"><li>Bit 0 (<code>Repeat Message Request</code>) fordert den Repeat Message State an.\n</li><li>Bit 3 (<code>NM Coordinator Sleep Ready</code>) übermittelt die Schlafbereitschaft eines Koordinators.\n</li><li>Bit 4 (<code>Active Wakeup Bit</code>) signalisiert, dass der Knoten das Netzwerk aktiv aufgeweckt hat (Diagnose- und Tracking-Zwecke).\n</li><li>Bit 6 (<code>PNI Bit</code>) indiziert, ob im Datenteil der NM-Nachricht Partial-Network-Filtervektoren enthalten sind und ausgewertet werden müssen.\n</li><li>Bits 7, 5 sowie 2–1 verbleiben reserviert.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwicklungs- und Integrationshinweise:</p>\n<ul class=\"fig-list\"><li>Die Bitpositionen sind bei der Serialisierung und Deserialisierung des CBV strikt nach der Spezifikation zu decodieren.\n</li><li>Bit 6 (<code>PNI Bit</code>) bestimmt die Interpretation nachfolgender Bytes bezüglich Partial-Network-Clusteranforderungen.\n</li><li>Bit 4 (<code>Active Wakeup Bit</code>) muss bei aktiver Weckursache gesetzt und bei passivem Wecken gelöscht übertragen werden.\n</li><li>Reservierte Bits (Bits 7, 5, 2, 1) sind konform zu den Initialisierungsregeln zu handhaben.\n</li></ul>"}, {"id": "FIG-c2bbcd34447cfca5", "releases": ["R4.3.1", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt die Bitbelegung des Control Bit Vector (CBV) innerhalb der UdpNm-PDU dar. Im AUTOSAR-UdpNm-Architekturkontext definiert diese tabellarische Bitfeld-Spezifikation die Kontrollflags zur Netzwerkzustandssteuerung und Partial-Networking-Unterstützung über Ethernet/UDP.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist das Byte <code>CBV</code> mit den Bitpositionen Bit 7 bis Bit 0:</p>\n<ul class=\"fig-list\"><li>Bit 7: Reserviert (<code>Res</code>)\n</li><li>Bit 6: <code>PNI Bit</code> (Partial Network Information Bit)\n</li><li>Bit 5: Reserviert (<code>Res</code>)\n</li><li>Bit 4: <code>Active Wakeup Bit</code>\n</li><li>Bit 3: <code>NM Coordinator Sleep Ready</code>\n</li><li>Bit 2: Reserviert (<code>Res</code>), mit Hinweistext <code>R3.2 NM Coordinator ID (High Bit)</code>\n</li><li>Bit 1: Reserviert (<code>Res</code>), mit Hinweistext <code>R3.2 NM Coordinator ID (Low Bit)</code>\n</li><li>Bit 0: <code>Repeat Message Request</code>\n</li></ul>\n<p class=\"fig-p\">Das CBV-Feld fungiert als standardisierter Kommunikationsheader innerhalb des User-Data- bzw. Steuerdatenbereichs der NM-Nachricht.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Signalbits beeinflussen das Zustandsverhalten des NM-Stacks:</p>\n<ul class=\"fig-list\"><li>Bit 0 (<code>Repeat Message Request</code>) fordert den Repeat Message State an.\n</li><li>Bit 3 (<code>NM Coordinator Sleep Ready</code>) übermittelt die Schlafbereitschaft eines Koordinators.\n</li><li>Bit 4 (<code>Active Wakeup Bit</code>) signalisiert, dass der Knoten das Netzwerk aktiv aufgeweckt hat (Diagnose- und Tracking-Zwecke).\n</li><li>Bit 6 (<code>PNI Bit</code>) indiziert, ob im Datenteil der NM-Nachricht Partial-Network-Filtervektoren enthalten sind und ausgewertet werden müssen.\n</li><li>Bits 7, 5 sowie 2–1 verbleiben reserviert.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwicklungs- und Integrationshinweise:</p>\n<ul class=\"fig-list\"><li>Die Bitpositionen sind bei der Serialisierung und Deserialisierung des CBV strikt nach der Spezifikation zu decodieren.\n</li><li>Bit 6 (<code>PNI Bit</code>) bestimmt die Interpretation nachfolgender Bytes bezüglich Partial-Network-Clusteranforderungen.\n</li><li>Bit 4 (<code>Active Wakeup Bit</code>) muss bei aktiver Weckursache gesetzt und bei passivem Wecken gelöscht übertragen werden.\n</li><li>Reservierte Bits (Bits 7, 5, 2, 1) sind konform zu den Initialisierungsregeln zu handhaben.\n</li></ul>"}, {"id": "FIG-aa3bf2cfdd4e4ed1", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt die Bitbelegung des Control Bit Vector (CBV) innerhalb der UdpNm-PDU dar. Im AUTOSAR-UdpNm-Architekturkontext definiert diese tabellarische Bitfeld-Spezifikation die Kontrollflags zur Netzwerkzustandssteuerung und Partial-Networking-Unterstützung über Ethernet/UDP.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist das Byte <code>CBV</code> mit den Bitpositionen Bit 7 bis Bit 0:</p>\n<ul class=\"fig-list\"><li>Bit 7: Reserviert (<code>Res</code>)\n</li><li>Bit 6: <code>PNI Bit</code> (Partial Network Information Bit)\n</li><li>Bit 5: Reserviert (<code>Res</code>)\n</li><li>Bit 4: <code>Active Wakeup Bit</code>\n</li><li>Bit 3: <code>NM Coordinator Sleep Ready</code>\n</li><li>Bit 2: Reserviert (<code>Res</code>), mit Hinweistext <code>R3.2 NM Coordinator ID (High Bit)</code>\n</li><li>Bit 1: Reserviert (<code>Res</code>), mit Hinweistext <code>R3.2 NM Coordinator ID (Low Bit)</code>\n</li><li>Bit 0: <code>Repeat Message Request</code>\n</li></ul>\n<p class=\"fig-p\">Das CBV-Feld fungiert als standardisierter Kommunikationsheader innerhalb des User-Data- bzw. Steuerdatenbereichs der NM-Nachricht.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Signalbits beeinflussen das Zustandsverhalten des NM-Stacks:</p>\n<ul class=\"fig-list\"><li>Bit 0 (<code>Repeat Message Request</code>) fordert den Repeat Message State an.\n</li><li>Bit 3 (<code>NM Coordinator Sleep Ready</code>) übermittelt die Schlafbereitschaft eines Koordinators.\n</li><li>Bit 4 (<code>Active Wakeup Bit</code>) signalisiert, dass der Knoten das Netzwerk aktiv aufgeweckt hat (Diagnose- und Tracking-Zwecke).\n</li><li>Bit 6 (<code>PNI Bit</code>) indiziert, ob im Datenteil der NM-Nachricht Partial-Network-Filtervektoren enthalten sind und ausgewertet werden müssen.\n</li><li>Bits 7, 5 sowie 2–1 verbleiben reserviert.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwicklungs- und Integrationshinweise:</p>\n<ul class=\"fig-list\"><li>Die Bitpositionen sind bei der Serialisierung und Deserialisierung des CBV strikt nach der Spezifikation zu decodieren.\n</li><li>Bit 6 (<code>PNI Bit</code>) bestimmt die Interpretation nachfolgender Bytes bezüglich Partial-Network-Clusteranforderungen.\n</li><li>Bit 4 (<code>Active Wakeup Bit</code>) muss bei aktiver Weckursache gesetzt und bei passivem Wecken gelöscht übertragen werden.\n</li><li>Reservierte Bits (Bits 7, 5, 2, 1) sind konform zu den Initialisierungsregeln zu handhaben.\n</li></ul>"}, {"id": "FIG-a92308d568da3d7c", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt die Bitbelegung des Control Bit Vector (CBV) innerhalb der UdpNm-PDU dar. Im AUTOSAR-UdpNm-Architekturkontext definiert diese tabellarische Bitfeld-Spezifikation die Kontrollflags zur Netzwerkzustandssteuerung und Partial-Networking-Unterstützung über Ethernet/UDP.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist das 8-Bit-Feld <code>CBV</code> mit den Bitpositionen Bit 7 bis Bit 0:</p>\n<ul class=\"fig-list\"><li>Bit 7: Reserviert (<code>Res</code>)\n</li><li>Bit 6: <code>PNI Bit</code> (Partial Network Information Bit)\n</li><li>Bit 5: <code>Partial Network Learning Bit</code>\n</li><li>Bit 4: <code>Active Wakeup Bit</code>\n</li><li>Bit 3: <code>NM Coordinator Sleep Ready</code>\n</li><li>Bit 2: Reserviert (<code>Res</code>)\n</li><li>Bit 1: <code>PN Shutdown Request Bit</code>\n</li><li>Bit 0: <code>Repeat Message Request</code>\n</li></ul>\n<p class=\"fig-p\">Die Struktur definiert die Schnittstellen-Steuerbits zur erweiterten Koordination von Teilnetzwerken und Netzwerkzuständen in der UdpNm-PDU.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablauf- und Zustandsverhalten:</p>\n<ul class=\"fig-list\"><li>Bit 0 (<code>Repeat Message Request</code>) triggert den Repeat Message State.\n</li><li>Bit 1 (<code>PN Shutdown Request Bit</code>) signalisiert eine koordinierte Herunterfahranforderung für Partial Networks.\n</li><li>Bit 3 (<code>NM Coordinator Sleep Ready</code>) koordiniert den synchronen Übergang in den Schlafmodus.\n</li><li>Bit 4 (<code>Active Wakeup Bit</code>) markiert aktive Weckereignisse.\n</li><li>Bit 5 (<code>Partial Network Learning Bit</code>) steuert und kennzeichnet Lernvorgänge für die dynamische Zuordnung von Teilnetzwerken.\n</li><li>Bit 6 (<code>PNI Bit</code>) signalisiert das Vorhandensein gültiger Teilnetzwerk-Informationen in der NM-PDU.\n</li><li>Bits 7 und 2 fungieren als reservierte Bits ohne dynamische Steuerfunktion.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Relevanz:</p>\n<ul class=\"fig-list\"><li>Bit 1 (<code>PN Shutdown Request Bit</code>) und Bit 5 (<code>Partial Network Learning Bit</code>) erweitern das Partial-Networking-Protokollverhalten normativ um kontrolliertes Abschalten und dynamisches Erlernen von Partial-Network-Zuordnungen.\n</li><li>Nicht belegte Bits (Bit 7 und Bit 2) sind nach AUTOSAR-Vorgabe reserviert (<code>Res</code>) zu halten (Standardwert 0) und dürfen nicht zweckentfremdet werden.\n</li></ul>"}, {"id": "FIG-4252da7b8b6cef10", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt die Bitbelegung des Control Bit Vector (CBV) innerhalb der UdpNm-PDU dar. Im AUTOSAR-UdpNm-Architekturkontext definiert diese tabellarische Bitfeld-Spezifikation die Kontrollflags zur Netzwerkzustandssteuerung und Partial-Networking-Unterstützung über Ethernet/UDP.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist das 8-Bit-Feld <code>CBV</code> mit den Bitpositionen Bit 7 bis Bit 0:</p>\n<ul class=\"fig-list\"><li>Bit 7: Reserviert (<code>Res</code>)\n</li><li>Bit 6: <code>PNI Bit</code> (Partial Network Information Bit)\n</li><li>Bit 5: <code>Partial Network Learning Bit</code>\n</li><li>Bit 4: <code>Active Wakeup Bit</code>\n</li><li>Bit 3: <code>NM Coordinator Sleep Ready</code>\n</li><li>Bit 2: Reserviert (<code>Res</code>)\n</li><li>Bit 1: <code>PN Shutdown Request Bit</code>\n</li><li>Bit 0: <code>Repeat Message Request</code>\n</li></ul>\n<p class=\"fig-p\">Die Struktur definiert die Schnittstellen-Steuerbits zur erweiterten Koordination von Teilnetzwerken und Netzwerkzuständen in der UdpNm-PDU.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablauf- und Zustandsverhalten:</p>\n<ul class=\"fig-list\"><li>Bit 0 (<code>Repeat Message Request</code>) triggert den Repeat Message State.\n</li><li>Bit 1 (<code>PN Shutdown Request Bit</code>) signalisiert eine koordinierte Herunterfahranforderung für Partial Networks.\n</li><li>Bit 3 (<code>NM Coordinator Sleep Ready</code>) koordiniert den synchronen Übergang in den Schlafmodus.\n</li><li>Bit 4 (<code>Active Wakeup Bit</code>) markiert aktive Weckereignisse.\n</li><li>Bit 5 (<code>Partial Network Learning Bit</code>) steuert und kennzeichnet Lernvorgänge für die dynamische Zuordnung von Teilnetzwerken.\n</li><li>Bit 6 (<code>PNI Bit</code>) signalisiert das Vorhandensein gültiger Teilnetzwerk-Informationen in der NM-PDU.\n</li><li>Bits 7 und 2 fungieren als reservierte Bits ohne dynamische Steuerfunktion.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Relevanz:</p>\n<ul class=\"fig-list\"><li>Bit 1 (<code>PN Shutdown Request Bit</code>) und Bit 5 (<code>Partial Network Learning Bit</code>) erweitern das Partial-Networking-Protokollverhalten normativ um kontrolliertes Abschalten und dynamisches Erlernen von Partial-Network-Zuordnungen.\n</li><li>Nicht belegte Bits (Bit 7 und Bit 2) sind nach AUTOSAR-Vorgabe reserviert (<code>Res</code>) zu halten (Standardwert 0) und dürfen nicht zweckentfremdet werden.\n</li></ul>"}], "trans": [{"from": "FIG-128c9f9600d839f4", "to": "FIG-b413aad2fd9901b5", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Zeilenbezeichnung links: Von <code>Byte 1</code> in <code>CBV</code> geändert.\n</li><li>Bit 6: Von Reserviert (<code>Res</code>) zu <code>PNI Bit</code> (Partial Network Information) geändert.\n</li><li>Bit 4: Von Reserviert (<code>Res</code>) zu <code>Active Wakeup Bit</code> geändert.\n</li><li>Bit 0: Beschriftung von <code>RptMsgRequest</code> zu zweizeiligem <code>Repeat Message Request</code> redaktionell präzisiert.\n</li></ul>"}, {"from": "FIG-b413aad2fd9901b5", "to": "FIG-225da6df9d79a652", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-225da6df9d79a652", "to": "FIG-c2bbcd34447cfca5", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c2bbcd34447cfca5", "to": "FIG-aa3bf2cfdd4e4ed1", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-aa3bf2cfdd4e4ed1", "to": "FIG-c2bbcd34447cfca5", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c2bbcd34447cfca5", "to": "FIG-a92308d568da3d7c", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Bit 5: Von Reserviert (<code>Res</code>) zu <code>Partial Network Learning Bit</code> geändert.\n</li><li>Bit 2: Der ausgegraute Altvermerk <code>Res R3.2 NM Coordinator ID (High Bit)</code> entfällt, Feldbelegung ist schlicht Reserviert (<code>Res</code>).\n</li><li>Bit 1: Von Reserviert / Althinweis (<code>Res R3.2 NM Coordinator ID (Low Bit)</code>) zu <code>PN Shutdown Request Bit</code> geändert.\n</li></ul>"}, {"from": "FIG-a92308d568da3d7c", "to": "FIG-4252da7b8b6cef10", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
